"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41315"],{61734(e){e.exports=JSON.parse('{"id":"FIN-842","slug":"direct-debit","term":"Direct Debit","also_known_as":[],"difficulty":"Beginner","definition":"A direct debit is an arrangement, common in the United Kingdom and Europe, that authorises an organisation to collect payments directly from a customer\'s bank account, with amounts and dates that can vary.","explanation":["With a direct debit, the customer gives permission to a company, such as an energy supplier, gym or insurer, to take money from their account. The company then collects payments as they fall due. Because the company initiates each payment, the amount can change, as long as the customer is notified in advance.","In the United Kingdom, direct debits are protected by the Direct Debit Guarantee, which entitles customers to an immediate refund from their bank if a payment is taken in error. In the euro area, the Single Euro Payments Area direct debit scheme provides similar protection and allows direct debits across countries.","For example, a household might pay its electricity bill by direct debit, with the amount varying each month based on usage, or its council tax in fixed monthly instalments.","Direct debits make regular payments convenient and help avoid late fees. Customers can cancel them through their bank. Similar arrangements in the United States are often called automatic payments, autopay or ACH debits."],"note":"","total":1500,"prev":{"slug":"direct-cost","term":"Direct Cost"},"next":{"slug":"directors-and-officers-insurance","term":"Directors and Officers Insurance (D&O)"}}')}}]);